(function(root){
const roles=['Teaching Assistant','Rubric & Feedback','Admissions','Registration','Advising','Support','Knowledge','Analyst','Workflow','Compliance','Accessibility','Custom'];
const packs=['Learning guide','Registration guide','Support guide','Course materials'];
const skills=['Answer with sources','Explain concepts','Suggest next steps','Draft educator feedback','Analyze aggregate trends','Draft workflow proposal'];
const staffSkills=skills.slice(3);
const refusal='I can help you understand concepts and practice, but I cannot complete graded work, disclose unreleased content, change grades, or access another institution’s data.';
const abstain='I cannot verify this answer from the approved knowledge available to this agent.';
function defaults(role){return {role,name:role+' Agent',audience:['Rubric & Feedback','Analyst','Workflow','Compliance'].includes(role)?'staff':'student',scope:'course',course:'AIM310',instructions:'Use approved sources. Support learning. Escalate uncertain answers to a human.',packs:[role==='Registration'?'Registration guide':role==='Support'?'Support guide':'Learning guide'],skills:['Answer with sources',...(role==='Rubric & Feedback'?['Draft educator feedback']:[])]};}
function validate(d,actor){if(!['admin','faculty'].includes(actor))throw Error('A staff demo workspace is required.');if(actor==='faculty'&&(d.scope!=='course'||d.course!=='AIM310'))throw Error('Faculty can build only for their assigned demo course AIM310.');if(!d.name.trim()||!d.instructions.trim()||!d.packs.length||!d.skills.length)throw Error('Complete the name, instructions, packs and skills.');if(d.audience==='student'&&d.skills.some(s=>staffSkills.includes(s)))throw Error('Staff-only skills cannot be assigned to student-facing agents.');if(/ignore.*(rules|policy|instructions)|bypass|override.*(policy|rules)|disable.*(safety|guard)/i.test(d.instructions))throw Error('Instructions that bypass the learning policy are refused.');return true;}
function activate(d,actor,previous){validate(d,actor);return JSON.parse(JSON.stringify({...d,version:(previous?.version||0)+1,activatedAt:new Date().toISOString()}));}
function redact(s){return s.replace(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi,'[email]').replace(/\b\d[\d ()+.-]{7,}\d\b/g,'[number]').replace(/\b(my name is|i am called)\s+[a-z]+(?:\s+[a-z]+)?/gi,'[name]');}
function answer(question,agent,knowledge,course){if(agent.scope==='course'&&agent.course!==course)return {outcome:'refused',text:refusal,sources:[]};if(/(do|write|complete|solve).*(graded|assignment|exam)|unreleased|change.*grade|another (school|institution)|other school/i.test(question))return {outcome:'refused',text:refusal,sources:[]};const words=question.toLowerCase().match(/[a-z]{3,}/g)||[];const candidates=knowledge.filter(k=>k.approved&&agent.packs.includes(k.pack)&&(!k.course||k.course===course)).map(k=>({k,score:k.keywords.filter(w=>words.includes(w.toLowerCase())).length})).sort((a,b)=>b.score-a.score);const k=candidates[0]?.score?candidates[0].k:null;return k?{outcome:'answered',text:(agent.audience==='staff'?'AI DRAFT — REQUIRES HUMAN EDUCATOR REVIEW\n':'')+k.answer,sources:[k.id]}:{outcome:'unverified',text:abstain,sources:[]};}
function measure(base,current){if(!base.opportunities||current.opportunities<5)return 'Insufficient observations';return current.count/current.opportunities<base.count/base.opportunities?'Improved':'No improvement observed';}
const api={roles,packs,skills,staffSkills,defaults,validate,activate,redact,answer,measure,refusal,abstain};if(typeof module!=='undefined')module.exports=api;else root.AgentCore=api;
})(globalThis);
